import{c as s,J as e,h as c,k as i}from"./chunks/framework.NhpCCunm.js";const g=JSON.parse('{"title":"Production Economics & Business Guides","description":"Practical guides on manufacturing economics, pricing formulas, unit costing, and business accounting for workshops and small producers.","frontmatter":{"title":"Production Economics & Business Guides","description":"Practical guides on manufacturing economics, pricing formulas, unit costing, and business accounting for workshops and small producers."},"headers":[],"relativePath":"articles/index.md","filePath":"articles/index.md"}'),r={name:"articles/index.md"};function n(t,a,o,d,l,p){return e(),c("div",null,[...a[0]||(a[0]=[i('<h1 id="production-economics-business-guides" tabindex="-1">Production Economics &amp; Business Guides <a class="header-anchor" href="#production-economics-business-guides" aria-label="Permalink to &quot;Production Economics &amp; Business Guides&quot;">​</a></h1><p>A knowledge base of actionable workflows and financial guides for craftsmen, custom workshops, and small production studios. We share real-world shop experience: no academic fluff, no corporate buzzwords, and no illusions of effortless wealth.</p><hr><div class="calc-promo-banner"><div class="promo-text-wrap"><div class="promo-badge">Interactive Tools</div><div class="promo-title">Online Product Cost Calculators</div><div class="promo-desc">7 industry-specific calculators accounting for scrap margins, processing losses, components, and direct estimate export to Excel.</div></div><a href="/calculators/" class="promo-btn">All Calculators →</a></div><hr><h2 id="methodology-guides-business-analytics" tabindex="-1">Methodology Guides &amp; Business Analytics <a class="header-anchor" href="#methodology-guides-business-analytics" aria-label="Permalink to &quot;Methodology Guides &amp; Business Analytics&quot;">​</a></h2><div class="articles-feed"><div class="article-card featured-card"><div class="card-badges"><span class="badge-tag">Economics</span><span class="badge-tag">Pricing</span><span class="badge-tag">Flagship Guide</span></div><div class="card-title"><a href="/articles/pricing-and-margins"> Pricing, Markup &amp; Gross Margin: How to Price Products Without Working at a Loss </a></div><p class="card-desc"> Unpacking the critical financial difference between retail markup and gross profit margin: why a 40% markup produces only a 28% margin, how to set sustainable selling prices from direct unit costs, and how to pinpoint your workshop breakeven volume. Includes an interactive markup and margin calculator. </p><div class="card-footer"><span class="read-time">Interactive calculation: ~5 minutes</span><a href="/articles/pricing-and-margins" class="card-link"> Read Guide &amp; Calculate Margins → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Software &amp; Accounting</span><span class="badge-tag">Automation</span><span class="badge-tag">Workshop</span></div><div class="card-title"><a href="/articles/cost-calculation-software"> Cost Calculation Software: Why Generic Spreadsheets and Corporate ERPs Fail Small Studios </a></div><p class="card-desc"> The evolution of shop bookkeeping: from paper notepads to spreadsheet tables and enterprise ERP suites. We break down silent formula errors, moving average cost tracking (MAC), and fundamental requirements for specialized local software. </p><div class="card-footer"><span class="read-time">Reading time: ~7 minutes</span><a href="/articles/cost-calculation-software" class="card-link"> Read Guide → </a></div></div></div><hr><h2 id="industry-economics-material-loss-breakdowns" tabindex="-1">Industry Economics &amp; Material Loss Breakdowns <a class="header-anchor" href="#industry-economics-material-loss-breakdowns" aria-label="Permalink to &quot;Industry Economics &amp; Material Loss Breakdowns&quot;">​</a></h2><div class="articles-feed"><div class="article-card"><div class="card-badges"><span class="badge-tag">Leathercraft</span><span class="badge-tag">Process Loss</span></div><div class="card-title"><a href="/calculators/leather-cost-calculator"> Leather Workshop Economics: The Hide Scrap Trap and Real Product Cost </a></div><p class="card-desc"> Analyzing two critical financial pitfalls in leatherworking: why hides cannot be priced strictly by clean pattern dimensions, how much money vanishes into scrap trimmings under the workbench (up to 35%), and how to accurately cost hand-stitching labor. </p><div class="card-footer"><span class="read-time">Reading time: ~8 minutes</span><a href="/calculators/leather-cost-calculator" class="card-link"> Read Guide &amp; Open Calculator → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">3D Printing</span><span class="badge-tag">Engineering</span></div><div class="card-title"><a href="/calculators/3d-print-cost-calculator"> 3D Printing Economics: Support Overhead, Calibration Waste, and Machine Wear </a></div><p class="card-desc"> An engineering breakdown for 3D printing studios and rapid prototyping shops. Slicer weight vs actual spool consumption, support and purge tower overhead (15–20%), brass threaded inserts (M3/M4), nozzle wear, and operator billable hours. </p><div class="card-footer"><span class="read-time">Reading time: ~7 minutes</span><a href="/calculators/3d-print-cost-calculator" class="card-link"> Read Guide &amp; Open Calculator → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Commercial Kitchens</span><span class="badge-tag">Food Costing</span></div><div class="card-title"><a href="/calculators/dish-cost-calculator"> Kitchen &amp; Catering Economics: Tech-Cards, Food Cost Percentages, and Thermal Losses </a></div><p class="card-desc"> Standardized culinary costing methodology for chefs, commercial kitchens, and catering providers. Gross-to-net conversions, cooking and frying shrinkage (up to 35%), portioned spices, vacuum pouches, and nutrition labeling. </p><div class="card-footer"><span class="read-time">Reading time: ~7 minutes</span><a href="/calculators/dish-cost-calculator" class="card-link"> Read Guide &amp; Open Calculator → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Pastry &amp; Baking</span><span class="badge-tag">Oven Evaporation</span></div><div class="card-title"><a href="/calculators/cake-cost-calculator"> Bakery Economics: Raw Batches, Oven Evaporation Loss, and Packaging Margins </a></div><p class="card-desc"> Specialized analysis for cake designers and artisanal bakeries: calculating batter mixing volume, baking moisture loss (10–14%), cream-cheese costs, fresh fruit, heavy-duty moisture-resistant cake boards, and transport packaging. </p><div class="card-footer"><span class="read-time">Reading time: ~7 minutes</span><a href="/calculators/cake-cost-calculator" class="card-link"> Read Guide &amp; Open Calculator → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Candle Making</span><span class="badge-tag">Handmade Crafts</span></div><div class="card-title"><a href="/calculators/candle-cost-calculator"> Candle Studio Economics: Wax Density, Fragrance Loading, and Pitcher Residue </a></div><p class="card-desc"> A practical guide for candle and soap artisans. Converting liquid container volume (ml) to solid wax mass (g), calculating exact fragrance loads (8–10%), wooden wicks, pitcher wall residue, and gift box packaging. </p><div class="card-footer"><span class="read-time">Reading time: ~6 minutes</span><a href="/calculators/candle-cost-calculator" class="card-link"> Read Guide &amp; Open Calculator → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Salon Services</span><span class="badge-tag">Nail Tech</span></div><div class="card-title"><a href="/calculators/beauty-cost-calculator"> Nail Studio Economics: Per-Client Procedure Costing, Sterilization, and Booth Rent </a></div><p class="card-desc"> Professional cost breakdown for nail technicians and salon suites. Single-use abrasive files, base and gel polish consumption per client, autoclave pouch sterilization compliance, and hourly station booth rent. </p><div class="card-footer"><span class="read-time">Reading time: ~6 minutes</span><a href="/calculators/beauty-cost-calculator" class="card-link"> Read Guide &amp; Open Calculator → </a></div></div><div class="article-card"><div class="card-badges"><span class="badge-tag">Baseline Costing</span><span class="badge-tag">All Products</span></div><div class="card-title"><a href="/calculators/product-cost-calculator"> Universal Product Costing: Materials, Defect Allowances, and Labor Billing </a></div><p class="card-desc"> Universal unit costing principles for any craft or assembly process: tracking raw materials, scrap margins, components, craftsman labor rates, and machine wear with direct Excel (.xlsx) export. </p><div class="card-footer"><span class="read-time">Reading time: ~6 minutes</span><a href="/calculators/product-cost-calculator" class="card-link"> Read Guide &amp; Open Calculator → </a></div></div></div>',10)])])}const m=s(r,[["render",n]]);export{g as __pageData,m as default};
